#include <iostream>

#include <vector>

#include <sstream>

#include <iomanip>

#include <cmath>

using namespace std;

bool isPrime(long long x){if(x<2)return false;for(long long d=2;d*d<=x;d++)if(x%d==0)return false;return true;}

string average(long long sum,long long count,int places){

 if(!count){return places?string("0.")+string(places,'0'):"0";}

 long long scale=1;for(int j=0;j<places;j++)scale*=10;

 long long a=sum<0?-sum:sum;

 long long rounded=(2*a*scale+count)/(2*count);

 ostringstream out;if(sum<0&&rounded)out<<'-';

 out<<rounded/scale;

 if(places)out<<'.'<<setw(places)<<setfill('0')<<(rounded%scale);

 return out.str();

}

int main(){ios::sync_with_stdio(false);cin.tie(nullptr);

int n;cin>>n;vector<long long>a(n);for(auto &v:a)cin>>v;

long long sum=0,count=0;for(auto v:a)if(isPrime(v)){sum+=v;count++;}cout<<average(sum,count,1)<<'\n';
}
